<script setup lang="ts">
import { onMounted, ref } from 'vue'; import AppState from '../../components/AppState.vue'; import UiButton from '../../components/UiButton.vue'; import UiSwitch from '../../components/UiSwitch.vue'; import { api } from '../../lib/api'
const enabled=ref(false);const loading=ref(true);const saved=ref('');const error=ref('');const origin=window.location.origin;onMounted(async()=>{try{enabled.value=(await api<any>('/api/v1/admin/compatibility')).legacy.enabled}catch(e){error.value=e instanceof Error?e.message:'Falha ao carregar.'}finally{loading.value=false}});async function save(){try{await api('/api/v1/admin/compatibility',{method:'PUT',body:JSON.stringify({enabled:enabled.value})});saved.value='Compatibilidade atualizada.';error.value=''}catch(e){error.value=e instanceof Error?e.message:'Falha ao salvar.'}}
</script>
<template><div><header class="page-header"><p class="eyebrow">Clientes e dispositivos</p><h1>Compatibilidade</h1><p>Controle o cliente conservador para navegadores antigos.</p></header><AppState v-if="loading" kind="loading" /><section v-else class="settings-section"><p v-if="saved" class="alert alert--success" role="status">{{ saved }}</p><p v-if="error" class="alert alert--error" role="alert">{{ error }}</p><UiSwitch v-model="enabled" label="Cliente legacy" description="Disponibiliza uma interface simplificada em /legacy para WebKit antigo e iOS 10." /><dl class="compat-list"><div><dt>URL</dt><dd><a href="/legacy">{{ origin }}/legacy</a></dd></div><div><dt>Fluxos suportados</dt><dd>Login, biblioteca, busca, detalhes, leitura EPUB/PDF e progresso</dd></div><div><dt>PDF</dt><dd>Navegação por página, zoom e restauração usando o visualizador nativo do dispositivo</dd></div></dl><UiButton variant="primary" @click="save">Salvar alterações</UiButton></section></div></template>
